package local.skyfamily;
import java.net.*;import java.io.*;import java.util.*;import android.graphics.BitmapFactory;
final class UploadReceiver {
 final ServerSocket server;final InetAddress address;final String secret=UUID.randomUUID().toString().replace("-","");final File folder;final Runnable uploaded;final long expires=System.currentTimeMillis()+900000L;volatile boolean open=true;
 UploadReceiver(InetAddress ip,File dir,Runnable callback)throws Exception{address=ip;folder=dir;uploaded=callback;if(!folder.exists()&&!folder.mkdirs())throw new IOException("Cannot create upload folder");server=new ServerSocket();server.bind(new InetSocketAddress(ip,0));server.setSoTimeout(2000);Thread thread=new Thread(()->run(),"sky-local-upload");thread.setDaemon(true);thread.start();}
 String url(){return "http://"+address.getHostAddress()+":"+server.getLocalPort()+"/"+secret;}
 void close(){open=false;try{server.close();}catch(Exception ignored){}}
 void run(){while(open&&System.currentTimeMillis()<expires){try{Socket socket=server.accept();socket.setSoTimeout(20000);try{serve(socket);}finally{socket.close();}}catch(SocketTimeoutException ignored){}catch(Exception ignored){}}close();}
 String line(InputStream in)throws IOException{ByteArrayOutputStream b=new ByteArrayOutputStream();for(int i=0;i<4096;i++){int c=in.read();if(c<0)throw new EOFException();if(c==10)return b.toString("US-ASCII").replace("\r","");b.write(c);}throw new IOException("Header line too long");}
 void reply(Socket s,int status,String type,String body)throws IOException{byte[] bytes=body.getBytes("UTF-8");String reason=status==200?"OK":"Rejected";OutputStream out=s.getOutputStream();out.write(("HTTP/1.1 "+status+" "+reason+"\r\nContent-Type: "+type+"; charset=utf-8\r\nContent-Length: "+bytes.length+"\r\nCache-Control: no-store\r\nX-Content-Type-Options: nosniff\r\nX-Frame-Options: DENY\r\nConnection: close\r\n\r\n").getBytes("US-ASCII"));out.write(bytes);out.flush();}
 void serve(Socket socket)throws Exception{InputStream in=socket.getInputStream();String[] request=line(in).split(" ");if(request.length!=3){reply(socket,400,"text/plain","Bad request");return;}HashMap<String,String> headers=new HashMap<>();int total=0;while(true){String h=line(in);total+=h.length();if(total>16384)throw new IOException("Too many headers");if(h.isEmpty())break;int colon=h.indexOf(':');if(colon<1)throw new IOException("Bad header");String key=h.substring(0,colon).trim().toLowerCase(Locale.US);if(headers.containsKey(key))throw new IOException("Duplicate header");headers.put(key,h.substring(colon+1).trim());}String route="/"+secret;if(!open||System.currentTimeMillis()>=expires){reply(socket,403,"text/plain","Session closed");return;}if(request[0].equals("GET")&&request[1].equals(route)){String html="<!doctype html><meta name='viewport' content='width=device-width,initial-scale=1'><title>Sky Family Upload</title><style>body{font:18px sans-serif;background:#10192a;color:#edf5ff;max-width:600px;margin:40px auto;padding:24px}button,input{font:inherit;padding:14px;margin:12px 0}button{background:#73dfcc;border:0;border-radius:12px}progress{width:100%}</style><h1>Send images to your frame</h1><p>Trusted LAN only. Transfer is unencrypted. JPEG, PNG, GIF or WebP supported by the frame; 10 MiB maximum each.</p><input id='files' type='file' accept='image/*' multiple><button id='send'>Send images</button><progress id='bar' max='100' value='0'></progress><pre id='status'></pre><script>var files=document.getElementById('files'),status=document.getElementById('status'),button=document.getElementById('send');button.onclick=function(){var list=files.files,i=0;button.disabled=true;function next(){if(i>=list.length){button.disabled=false;status.textContent+='Finished.\n';return;}var f=list[i++];if(f.size>10485760){status.textContent+=f.name+': too large\n';next();return;}var x=new XMLHttpRequest();x.open('POST',location.pathname+'/upload');x.setRequestHeader('X-Sky-Upload','"+secret+"');x.upload.onprogress=function(e){if(e.lengthComputable)document.getElementById('bar').value=100*e.loaded/e.total;};x.onload=function(){status.textContent+=f.name+': '+x.responseText+'\n';next();};x.onerror=function(){status.textContent+='Connection failed. Keep frame upload screen open.\n';button.disabled=false;};x.send(f);}next();};</script>";reply(socket,200,"text/html",html);return;}if(!request[0].equals("POST")||!request[1].equals(route+"/upload")||!secret.equals(headers.get("x-sky-upload"))||headers.containsKey("transfer-encoding")){reply(socket,403,"text/plain","Not allowed");return;}long length;try{length=Long.parseLong(headers.get("content-length"));}catch(Exception e){reply(socket,411,"text/plain","Content length required");return;}if(length<=0||length>10485760){reply(socket,413,"text/plain","Image must be at most 10 MiB");return;}File[] files=folder.listFiles();long used=0;int count=0;if(files!=null)for(File f:files){used+=f.length();count++;}if(count>=50||used+length>104857600L){reply(socket,413,"text/plain","Frame upload quota reached; delete old uploads");return;}File temp=File.createTempFile("incoming-",".part",folder);boolean saved=false;try{try(FileOutputStream out=new FileOutputStream(temp)){byte[] b=new byte[8192];long remaining=length;while(remaining>0){if(!open||System.currentTimeMillis()>=expires)throw new IOException("Session closed");int n=in.read(b,0,(int)Math.min(b.length,remaining));if(n<0)throw new EOFException();out.write(b,0,n);remaining-=n;}}BitmapFactory.Options options=new BitmapFactory.Options();options.inJustDecodeBounds=true;BitmapFactory.decodeFile(temp.getPath(),options);if(options.outWidth<=0||options.outHeight<=0||options.outWidth>8000||options.outHeight>8000||(long)options.outWidth*options.outHeight>20000000L){reply(socket,415,"text/plain","Unsupported image or too many pixels (20 MP limit)");return;}File target=new File(folder,"image-"+System.currentTimeMillis()+"-"+UUID.randomUUID().toString().substring(0,8)+".image");if(!temp.renameTo(target))throw new IOException("Cannot save image");saved=true;reply(socket,200,"text/plain","Saved on frame");uploaded.run();}finally{if(!saved)temp.delete();}}
}
